const rows = $input.all().map(i => i.json);

const actual = [];
const skipped = [];

for (const r of rows) {
  if (!r.reminder_id) continue;
  if (Number(r.новых_сессий) > 0) { skipped.push(r); continue; }
  actual.push(r);
}

const ids = [];
for (const r of actual) ids.push(r.reminder_id);
for (const r of skipped) ids.push(r.reminder_id);

let text = '';
for (const r of actual) {
  text += 'ОР: ' + r.or_name + ' — сотрудник ' + r.employee_name +
          ' (сессия #' + r.session_id + '). Пора назначить следующую встречу.\n';
}

return [{ json: {
  to_send:     actual.length,
  skipped:     skipped.length,
  ids_sql:     ids.length ? ids.join(',') : '0',
  items:       actual,
  digest:      text
}}];
